// ── Diyalog umgangssprachlich/formal kelime tespiti (tap-to-see-formal) ─────
function escapeRegExpDlg(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function buildDialogVocabIndex(vocabArr) {
  if (!vocabArr || vocabArr.length === 0) return null;
  const lookup = {};
  const phrases = [];
  vocabArr.forEach((v) => {
    v.de.split(' / ').forEach((variant) => {
      const t = variant.trim();
      if (!t) return;
      const key = t.toLowerCase();
      if (!lookup[key]) { lookup[key] = v; phrases.push(t); }
    });
  });
  if (phrases.length === 0) return null;
  phrases.sort((a, b) => b.length - a.length);
  const patterns = phrases.map((p) => {
    const esc = escapeRegExpDlg(p);
    const startsWord = /^[A-Za-zÀ-ÿ]/.test(p);
    const endsWord = /[A-Za-zÀ-ÿ]$/.test(p);
    let pat = esc;
    if (startsWord) pat = '(?<![A-Za-zÀ-ÿ])' + pat;
    if (endsWord) pat = pat + '(?![A-Za-zÀ-ÿ])';
    return pat;
  });
  const regex = new RegExp('(' + patterns.join('|') + ')', 'gi');
  return { regex, lookup };
}
