function renderDialogLine(text, vocabIdx, color, onWordClick) {
  if (!vocabIdx || !text) return text;
  const parts = text.split(vocabIdx.regex);
  return parts.map((part, i) => {
    if (i % 2 === 1) {
      const entry = vocabIdx.lookup[part.toLowerCase()];
      if (entry) {
        return (
          <span key={i}
            onClick={(e) => { e.stopPropagation(); onWordClick(entry, part, e); }}
            style={{ borderBottom: '1.5px dotted #C2410C', color: '#C2410C', cursor: 'pointer', fontWeight: 700 }}>
            {part}
          </span>
        );
      }
    }
    return <span key={i}>{part}</span>;
  });
}


// ── دەنگ / German text-to-speech (browser Web Speech API) ─────────
let _deVoice = null;
// ناوی دەنگە نێرینەکانی ئەڵمانی لە سیستەمە جیاوازەکاندا
const MALE_DE_NAMES = ["stefan", "conrad", "markus", "hans", "klaus", "daniel", "yannick", "bernd", "viktor", "männlich", "male"];
function pickGermanVoice() {
  try {
    const vs = window.speechSynthesis.getVoices();
    const de = vs.filter((v) => v.lang && v.lang.toLowerCase().startsWith("de"));
    // ١) دەنگی نێرینەی ئەڵمانی بەپێی ناو
    _deVoice =
      de.find((v) => MALE_DE_NAMES.some((n) => v.name.toLowerCase().includes(n))) ||
      // ٢) دەنگی de-DE
      de.find((v) => v.lang === "de-DE") ||
      // ٣) هەر دەنگێکی ئەڵمانی
      de[0] || null;
  } catch (e) {}
}
if (typeof window !== "undefined" && window.speechSynthesis) {
  pickGermanVoice();
  try { window.speechSynthesis.onvoiceschanged = pickGermanVoice; } catch (e) {}
}
function speakDe(text) {
  try {
    const synth = window.speechSynthesis;
    if (!synth || !text) return;
    synth.cancel();
    const u = new SpeechSynthesisUtterance(String(text));
    u.lang = "de-DE";
    if (_deVoice) u.voice = _deVoice;
    u.rate = 0.9;
    u.pitch = 0.8;
    u.volume = 1;
    synth.speak(u);
  } catch (e) {}
}

function Speak({ text, size = 15 }) {
  return (
    <button onClick={(e) => { e.stopPropagation(); speakDe(text); }}
      style={{ border: "none", background: "transparent", cursor: "pointer", color: C.gold, padding: "0 4px", lineHeight: 1, verticalAlign: "middle", flexShrink: 0, display:"inline-flex", alignItems:"center" }}>
      <Volume2 size={size} />
    </button>
  );
}

function LevelPills({ value, onChange }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 8, marginBottom: 20 }}>
      {LEVELS.map((lv) => {
        const active = value === lv.id;
        return (
          <button key={lv.id} onClick={() => onChange(lv.id)}
            style={{
              border: active ? "none" : `1.5px solid ${lv.color}33`,
              background: active ? lv.color : "#fff",
              color: active ? "#fff" : lv.color,
              padding: "11px 6px 10px",
              borderRadius: 14,
              fontWeight: 700,
              fontSize: 13,
              cursor: "pointer",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 3,
              boxShadow: active
                ? `0 3px 0 rgba(0,0,0,.12), 0 8px 20px ${lv.color}44`
                : "0 2px 0 rgba(0,0,0,.06), 0 4px 12px rgba(0,0,0,.05)",
              transition: "all .25s cubic-bezier(.34,1.56,.64,1)",
              transform: active ? "translateY(-1px)" : "none",
            }}>
            <span style={{ fontSize: 16, fontWeight: 800, lineHeight: 1 }}>{lv.id}</span>
            <span style={{ fontSize: 11, fontWeight: 600, opacity: active ? .9 : .75, letterSpacing: ".01em" }}>{lv.label}</span>
          </button>
        );
      })}
    </div>
  );
}

