// ── Mündlich A: Sich vorstellen ──────────────────────────────────────
function MündlichAItem({ ex, idx, lang = "ku" }) {
  const [openCards, setOpenCards] = useState({});
  function toggle(i) { setOpenCards(s => ({ ...s, [i]: !s[i] })); }
  function openAll() { const a = {}; ex.prompts.forEach((_, i) => a[i] = true); setOpenCards(a); }
  function closeAll() { setOpenCards({}); }
  return (
    <div style={{ marginBottom: 16, background: "#F9F9FB", borderRadius: 14, border: "1.5px solid #E4E4E8", padding: 14 }}>
      <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, marginBottom: 6 }}>{lang==="tr" ? `Alıştırma ${idx+1}` : lang==="en" ? `Exercise ${idx+1}` : lang==="ar" ? `تمرين ${idx+1}` : `تاقیکردنەوە ${idx+1}`}</div>
      <div style={{ background: "#FDF4FF", borderRadius: 10, padding: "8px 12px", marginBottom: 12, fontSize: 12.5, border: "1px solid #E9D5FF" }}>
        <span style={{ fontWeight: 700, color: "#7C3AED" }}>{ex.person}</span>
        <div style={{ fontSize: 11.5, color: C.muted, marginTop: 2 }}>{lang==="tr" ? (ex.personTr||ex.personKu) : lang==="en" ? (ex.personEn||ex.personKu) : lang==="ar" ? (ex.personAr||ex.personKu) : ex.personKu}</div>
      </div>
      <div style={{ fontSize: 11.5, color: C.muted, marginBottom: 8 }}>{lang==="tr" ? "Her karta tıklayarak örneği gör:" : lang==="en" ? "Tap each card to see the example:" : lang==="ar" ? "انقر كل بطاقة لرؤية المثال:" : "هەر کارتێک کلیک بکە نموونەکە ببینیت:"}</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 10 }}>
        {ex.prompts.map((p, i) => (
          <div key={i} onClick={() => toggle(i)}
            style={{ background: openCards[i] ? "#F0FDF4" : "#fff",
              border: `1.5px solid ${openCards[i] ? "#86EFAC" : "#E4E4E8"}`,
              borderRadius: 10, padding: "10px 12px", cursor: "pointer", transition: "all .15s", userSelect: "none" }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: openCards[i] ? "#16A34A" : "#7C3AED" }}>{p.topic}</div>
            <div style={{ fontSize: 11.5, color: C.muted, marginTop: 2 }} dir="ltr">{p.question}</div>
            {openCards[i] && (
              <div style={{ marginTop: 8, paddingTop: 8, borderTop: "1px solid #86EFAC" }}>
                <div style={{ fontSize: 12.5, fontWeight: 600, color: "#16A34A", lineHeight: 1.5 }} dir="ltr">✓ {p.example}</div>
                <div style={{ fontSize: 11.5, color: C.muted, marginTop: 3 }}>{tC(p, lang)}</div>
              </div>
            )}
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <button onClick={openAll}
          style={{ flex: 1, padding: "7px", borderRadius: 8, border: "none", background: "#7C3AED", color: "#fff", fontWeight: 700, fontSize: 12, cursor: "pointer" }}>
          {lang==="tr" ? "✓ Tüm örnekler" : lang==="en" ? "✓ All examples" : lang==="ar" ? "✓ كل الأمثلة" : "✓ هەموو نموونەکان"}
        </button>
        <button onClick={closeAll}
          style={{ flex: 1, padding: "7px", borderRadius: 8, border: "1.5px solid #E4E4E8", background: "#fff", color: C.muted, fontWeight: 700, fontSize: 12, cursor: "pointer" }}>
          {lang==="tr" ? "↺ Kapat" : lang==="en" ? "↺ Close" : lang==="ar" ? "↺ إغلاق" : "↺ داخستن"}
        </button>
      </div>
    </div>
  );
}

