              {content.responses.map((r, ri) => <div key={ri} dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif", fontSize: 14, padding: "3px 0" }}>{String.fromCharCode(97 + ri)}) {r}</div>)}
