                            <div style={{ fontSize:12, color: isSel ? ac : "#8B96AA", fontWeight:600, marginTop:2 }}>{l.words.length} {lang === "tr" ? "fiil" : lang === "en" ? "verb" : lang === "ar" ? "فعل" : "کردار"}</div>
