// shuffle helper
const shuffleArr = (arr) => [...arr].sort(()=>Math.random()-.5);

// ── SatzPuzzle ─────────────────────────────────────────────────────────
function SatzPuzzle({ lang = "ku", onBack }) {
  const SPT = {
    ku:{ title:"ساتز پازڵ", sub:"ڕستەیەک دروست بکە", start:"دەست پێبکە", back:"گەڕانەوە",
         score:"ئەنجام", restart:"دووبارە", correct:"دروستە! ✓", wrong:"هەڵەیە!",
         hint:"وەرگێڕان", check:"پشکنین", lvl_all:"هەموو ئاست", lvl_label:"ئاست هەڵبژێرە",
         tap_hint:"پەیەکان بکلێکە بۆ دروستکردنی ڕستە" },
    tr:{ title:"Satz Puzzle", sub:"Cümle kur", start:"Başla", back:"Geri",
         score:"Puan", restart:"Tekrar", correct:"Doğru! ✓", wrong:"Yanlış!",
         hint:"Çeviri", check:"Kontrol et", lvl_all:"Tüm seviyeler", lvl_label:"Seviye seç",
         tap_hint:"Kelimelere tıklayarak cümle kur" },
    en:{ title:"Satz Puzzle", sub:"Build a sentence", start:"Start", back:"Back",
         score:"Score", restart:"Restart", correct:"Correct! ✓", wrong:"Wrong!",
         hint:"Translation", check:"Check", lvl_all:"All levels", lvl_label:"Choose level",
         tap_hint:"Tap words to build the sentence" },
    ar:{ title:"Satz Puzzle", sub:"كوّن جملة", start:"ابدأ", back:"رجوع",
         score:"نتيجة", restart:"إعادة", correct:"صحيح! ✓", wrong:"خطأ!",
         hint:"الترجمة", check:"تحقق", lvl_all:"جميع المستويات", lvl_label:"اختر المستوى",
         tap_hint:"اضغط على الكلمات لبناء الجملة" },
  };
  const spt = k => (SPT[lang]||SPT.tr)[k] || (SPT.tr[k]||k);
  const LEVELS = ['All','A1','A2','B1','B2','C1'];
  const getNat = (item) => lang==='tr'?item.tr:lang==='ku'?item.ku:lang==='ar'?item.ar:item.en;
  const speak = (text) => {
    if(!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang='de-DE'; u.rate=0.82;
    window.speechSynthesis.speak(u);
  };

  const [phase,    setPhase]    = useState('setup');
  const [selLvl,   setSelLvl]   = useState('All');
  const [questions,setQuestions]= useState([]);
  const [qIdx,     setQIdx]     = useState(0);
  const [bank,     setBank]     = useState([]);   // available word chips {id,word}
  const [answer,   setAnswer]   = useState([]);   // placed chips
  const [status,   setStatus]   = useState(null); // null | 'correct' | 'wrong'
  const [score,    setScore]    = useState(0);
  const timerRef = useRef(null);

  const startGame = () => {
    let pool = selLvl==='All' ? SATZ_DATA : SATZ_DATA.filter(d=>d.lv===selLvl);
    if(pool.length < 5) pool = SATZ_DATA;
    const qs = shuffleArr(pool).slice(0,10);
    setQuestions(qs);
    setQIdx(0);
    setScore(0);
    loadQuestion(qs[0]);
    setPhase('game');
  };

  const loadQuestion = (q) => {
    const words = q.de.replace(/[.,!?]/g,'').split(' ').filter(Boolean);
    setBank(shuffleArr(words).map((w,i)=>({id:`${i}-${w}`,word:w})));
    setAnswer([]);
    setStatus(null);
  };

  const addWord = (chip) => {
    if(status) return;
    setBank(b=>b.filter(c=>c.id!==chip.id));
    setAnswer(a=>[...a,chip]);
  };

  const removeWord = (chip) => {
    if(status) return;
    setAnswer(a=>a.filter(c=>c.id!==chip.id));
    setBank(b=>[...b,chip]);
  };

  // Auto-check when all words placed
  useEffect(()=>{
    if(phase!=='game' || !questions[qIdx]) return;
    const q = questions[qIdx];
    const total = q.de.replace(/[.,!?]/g,'').split(' ').filter(Boolean).length;
    if(answer.length === total && bank.length === 0){
      checkAnswer();
    }
  },[answer, bank]);

  const checkAnswer = () => {
    const q = questions[qIdx];
    const correct = q.de.replace(/[.,!?]/g,'').split(' ').filter(Boolean);
    const given   = answer.map(c=>c.word);
    const isRight = JSON.stringify(correct)===JSON.stringify(given);
    setStatus(isRight ? 'correct' : 'wrong');
    if(isRight) setScore(s=>s+1);
    speak(q.de);
    timerRef.current = setTimeout(()=>{
      const nxt = qIdx+1;
      if(nxt >= questions.length){ setPhase('result'); }
      else {
        setQIdx(nxt);
        loadQuestion(questions[nxt]);
      }
    }, isRight ? 1300 : 2200);
  };

  useEffect(()=>()=>{if(timerRef.current)clearTimeout(timerRef.current);},[]);

  /* SETUP */
  if(phase==='setup') return (
    <div style={{maxWidth:480,margin:'0 auto',padding:'8px 0'}}>
      <button onClick={onBack} style={{background:'none',border:'none',color:'#888',cursor:'pointer',display:'flex',alignItems:'center',gap:6,fontSize:14,marginBottom:20}}>← {spt('back')}</button>
      <div style={{textAlign:'center',marginBottom:28}}>
        <div style={{fontSize:44}}>🧩</div>
        <div style={{fontWeight:800,fontSize:22,marginTop:8}}>{spt('title')}</div>
        <div style={{fontSize:14,color:'#888',marginTop:4}}>{spt('sub')}</div>
      </div>
      <div style={{background:'#fff',borderRadius:16,padding:18,marginBottom:22,border:'1px solid #ebebf0'}}>
        <div style={{fontSize:12,fontWeight:700,color:'#888',letterSpacing:'.06em',marginBottom:12}}>{spt('lvl_label')}</div>
        <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
          {LEVELS.map(lv=>(
            <button key={lv} onClick={()=>setSelLvl(lv)}
              style={{padding:'8px 16px',borderRadius:10,border:`2px solid ${selLvl===lv?'#30A46C':'#ddd'}`,
                background:selLvl===lv?'rgba(48,164,108,.1)':'#fff',color:selLvl===lv?'#30A46C':'#555',
                fontWeight:selLvl===lv?700:500,fontSize:14,cursor:'pointer',transition:'all .15s'}}>
              {lv==='All'?spt('lvl_all'):lv}
            </button>
          ))}
        </div>
      </div>
      <div style={{textAlign:'center',marginBottom:22,fontSize:13,color:'#888'}}>{spt('tap_hint')}</div>
      <button onClick={startGame}
        style={{width:'100%',padding:'14px',borderRadius:14,border:'none',background:'linear-gradient(135deg,#30A46C,#12a15a)',color:'#fff',fontWeight:700,fontSize:16,cursor:'pointer'}}>
        {spt('start')} →
      </button>
    </div>
  );

  /* RESULT */
  if(phase==='result'){
    const pct = Math.round((score/questions.length)*100);
    return (
      <div style={{maxWidth:420,margin:'0 auto',textAlign:'center',padding:'32px 0'}}>
        <div style={{fontSize:56}}>{pct>=80?'🏆':pct>=50?'👍':'💪'}</div>
        <div style={{fontWeight:800,fontSize:22,margin:'16px 0 6px'}}>{spt('score')}</div>
        <div style={{fontSize:52,fontWeight:900,color:'#30A46C',lineHeight:1}}>{score}<span style={{fontSize:22,color:'#aaa'}}> / {questions.length}</span></div>
        <div style={{fontSize:24,marginTop:6,fontWeight:700,color:pct>=70?'#30A46C':'#f97316'}}>{pct}%</div>
        <div style={{display:'flex',gap:12,marginTop:32,justifyContent:'center'}}>
          <button onClick={()=>setPhase('setup')} style={{padding:'12px 28px',borderRadius:12,border:'1px solid #ddd',background:'#fff',fontWeight:600,fontSize:15,cursor:'pointer'}}>{spt('back')}</button>
          <button onClick={startGame} style={{padding:'12px 28px',borderRadius:12,border:'none',background:'linear-gradient(135deg,#30A46C,#12a15a)',color:'#fff',fontWeight:700,fontSize:15,cursor:'pointer'}}>{spt('restart')}</button>
        </div>
      </div>
    );
  }

  /* GAME */
  const q = questions[qIdx];
  const correctWords = q.de.replace(/[.,!?]/g,'').split(' ').filter(Boolean);

  return (
    <div style={{maxWidth:520,margin:'0 auto'}}>
      {/* Progress bar */}
      <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:20}}>
        <button onClick={()=>{if(timerRef.current)clearTimeout(timerRef.current);setPhase('setup');}}
          style={{background:'none',border:'none',color:'#888',cursor:'pointer',fontSize:18}}>←</button>
        <div style={{flex:1,height:7,background:'#ebebf0',borderRadius:4}}>
          <div style={{height:'100%',width:`${(qIdx/questions.length)*100}%`,background:'linear-gradient(90deg,#30A46C,#12a15a)',borderRadius:4,transition:'width .4s'}}/>
        </div>
        <div style={{fontSize:13,color:'#888',fontWeight:600}}>{qIdx+1}/{questions.length}</div>
      </div>

      {/* Translation hint card */}
      <div style={{background:'#fff',borderRadius:20,padding:'18px 20px',marginBottom:16,border:'1px solid #ebebf0',boxShadow:'0 2px 12px rgba(0,0,0,.06)'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
          <div style={{display:'inline-block',padding:'3px 10px',borderRadius:20,background:'rgba(48,164,108,.1)',color:'#30A46C',fontSize:11,fontWeight:700,letterSpacing:'.08em'}}>{q.lv}</div>
          <button onClick={()=>speak(q.de)} style={{width:32,height:32,borderRadius:8,border:'1px solid #eee',background:'#f8f8fb',cursor:'pointer',fontSize:14}}>🔊</button>
        </div>
        <div style={{fontSize:13,color:'#666',fontWeight:500,marginBottom:4}}>{spt('hint')}</div>
        <div style={{fontSize:17,fontWeight:600,color:'#1a1a2e'}}>{getNat(q)}</div>
      </div>

      {/* Answer zone */}
      <div style={{minHeight:58,background:status==='correct'?'rgba(48,164,108,.08)':status==='wrong'?'rgba(229,72,77,.06)':'rgba(91,91,214,.04)',
        border:`2px dashed ${status==='correct'?'#30A46C':status==='wrong'?'#E5484D':'#c7c7e8'}`,
        borderRadius:16,padding:'10px 12px',marginBottom:16,display:'flex',flexWrap:'wrap',gap:8,alignItems:'center',minWidth:0,transition:'all .2s'}}>
        {answer.length===0 && !status &&
          <span style={{color:'#bbb',fontSize:13,fontStyle:'italic'}}>{spt('tap_hint')}</span>}
        {answer.map(chip=>(
          <button key={chip.id} onClick={()=>removeWord(chip)} disabled={!!status}
            style={{padding:'8px 14px',borderRadius:10,border:`1.5px solid ${status==='correct'?'#30A46C':status==='wrong'?'#E5484D':'#5B5BD6'}`,
              background:status==='correct'?'rgba(48,164,108,.15)':status==='wrong'?'rgba(229,72,77,.1)':'rgba(91,91,214,.08)',
              color:status==='correct'?'#30A46C':status==='wrong'?'#E5484D':'#5B5BD6',
              fontWeight:600,fontSize:15,cursor:status?'default':'pointer',transition:'all .15s'}}>
            {chip.word}
          </button>
        ))}
      </div>

      {/* Feedback */}
      {status && (
        <div style={{textAlign:'center',marginBottom:12,padding:'10px',borderRadius:12,
          background:status==='correct'?'rgba(48,164,108,.1)':'rgba(229,72,77,.08)',
          border:`1px solid ${status==='correct'?'#30A46C44':'#E5484D44'}`}}>
          <div style={{fontWeight:700,fontSize:16,color:status==='correct'?'#30A46C':'#E5484D'}}>
            {status==='correct' ? spt('correct') : spt('wrong')}
          </div>
          {status==='wrong' &&
            <div style={{fontSize:13,color:'#666',marginTop:4}}>{correctWords.join(' ')}</div>}
        </div>
      )}

      {/* Word bank */}
      <div style={{background:'#f8f8fb',borderRadius:16,padding:'12px',border:'1px solid #ebebf0',display:'flex',flexWrap:'wrap',gap:8}}>
        {bank.map(chip=>(
          <button key={chip.id} onClick={()=>addWord(chip)} disabled={!!status}
            style={{padding:'8px 14px',borderRadius:10,border:'1.5px solid #ddd',background:'#fff',
              color:'#1a1a2e',fontWeight:600,fontSize:15,cursor:status?'default':'pointer',
              boxShadow:'0 1px 4px rgba(0,0,0,.07)',transition:'all .15s'}}>
            {chip.word}
          </button>
        ))}
        {bank.length===0 && !status && <span style={{color:'#bbb',fontSize:13}}>—</span>}
      </div>
    </div>
  );
}

