const BOOK_DICT_KEYS = Object.keys(BOOK_DICT);

// ── Chapter quiz engine ──────────────────────────────────────────────────
// Extracts every BOOK_DICT word that actually appears in a chapter's narrative/dialogue
// lines (same tokenization renderWithDict uses), then builds a multiple-choice quiz from them.
function extractChapterWords(scenes) {
  const seen = new Set();
  const words = [];
  for (const scene of scenes) {
    for (const line of scene.lines || []) {
      if (line.t !== 'n' && line.t !== 'd') continue;
      if (!line.s) continue;
      for (const part of line.s.split(/\s+/)) {
        const clean = part.replace(/[.,!?;:"„"«»''()\[\]]+/g, '').toLowerCase();
        if (!clean || seen.has(clean)) continue;
        const entry = BOOK_DICT[clean];
        if (!entry) continue;
        seen.add(clean);
        words.push({ word: part.replace(/[.,!?;:"„"«»''()\[\]]+/g, ''), key: clean, entry });
      }
    }
  }
  return words;
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function buildChapterQuiz(scenes, lang = 'tr') {
  const chapterWords = shuffle(extractChapterWords(scenes)).slice(0, 10);
  const tField = lang === 'ku' ? 'ku' : 'tr';

  return chapterWords.map(({ word, key, entry }) => {
    const isNoun = entry.type === 'noun' && entry.article;
    const types = isNoun ? ['meaning', 'spelling', 'artikel'] : ['meaning', 'spelling'];
    const qType = types[Math.floor(Math.random() * types.length)];

    if (qType === 'artikel') {
      return { type: 'artikel', word, prompt: word, options: ['der', 'die', 'das'], correctIndex: ['der', 'die', 'das'].indexOf(entry.article) };
    }

    if (qType === 'meaning') {
      const others = shuffle(BOOK_DICT_KEYS.filter(k => k !== key)).slice(0, 2).map(k => BOOK_DICT[k][tField]);
      const options = shuffle([entry[tField], ...others]);
      return { type: 'meaning', word, prompt: word, options, correctIndex: options.indexOf(entry[tField]) };
    }

    // spelling: prefer same-type distractors for plausibility, fall back to any
    const sameType = BOOK_DICT_KEYS.filter(k => k !== key && BOOK_DICT[k].type === entry.type);
    const pool = sameType.length >= 2 ? sameType : BOOK_DICT_KEYS.filter(k => k !== key);
    const others = shuffle(pool).slice(0, 2).map(k => (BOOK_DICT[k].article ? BOOK_DICT[k].article + ' ' : '') + k);
    const correctLabel = (entry.article ? entry.article + ' ' : '') + key;
    const options = shuffle([correctLabel, ...others]);
    return { type: 'spelling', word, prompt: entry[tField], options, correctIndex: options.indexOf(correctLabel) };
  });
}

// ── ChapterQuiz — end-of-chapter comprehension gate ─────────────────────
